432	// CreateHandover 由交班班次向同岗位接班班次发起交接。
433	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
434	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
435	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
436	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
437	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
438	// 要求仅对首次发起生效。
439	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
440		fromShiftID = clean(fromShiftID)
441		toShiftID = clean(toShiftID)
442	
443		var result Handover
444		err := svc.store.mutate(func(d *Data) error {
445			from, _ := findShift(d, fromShiftID)
446			to, _ := findShift(d, toShiftID)
447			if from == nil {
448				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
449			}
450			if to == nil {
451				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
452			}
453			if from.ID == to.ID {
454				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
455			}
456			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
457			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
458			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
459			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
460			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
461			// 存在与交给自身的校验仍在其前。
462			for i := range d.Handovers {
463				if d.Handovers[i].FromShiftID == from.ID {
464					existing := &d.Handovers[i]
465					result = *existing
466					if existing.ToShiftID != to.ID {
467						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
468							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
469					}
470					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
471				}
472			}
473	
474			if from.Position != to.Position {
475				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
476					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
477			}
478	
479			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
480			// 交班班次已经结束，重叠区间须有说明。
481			if to.Closed {
482				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
483			}
484			if to.Start.Before(from.Start) {
485				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
486					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
487					from.ID, from.Start.Format(time.RFC3339))
488			}
489			if !from.Closed {
490				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
491					ErrShiftNotClosed, from.ID)
492			}
493			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
494				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
495					ErrOverlap, from.ID, to.ID)
496			}
497	
498			entries := []HandoverEntry{}
499			for i := range d.Items {
500				it := &d.Items[i]
501				if it.CurrentShiftID == from.ID && !it.Closed {
502					entries = append(entries, HandoverEntry{
503						ItemID:      it.ID,
504						Content:     it.Content,
505						Severity:    it.Severity,
506						Constraints: it.Constraints,
507						FollowOwner: it.FollowOwner,
508						Status:      EntryPending,
509					})
510				}
511			}
512			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
513	
514			d.HandoverSeq++
515			now := svc.now()
516			h := Handover{
517				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
518				Position:    from.Position,
519				FromShiftID: from.ID,
520				ToShiftID:   to.ID,
521				CreatedAt:   now,
522				Entries:     entries,
523			}
524			if len(entries) == 0 {
525				// 空清单直接完成。
526				h.CompletedAt = &now
527			}
528			d.Handovers = append(d.Handovers, h)
529			result = h
530			return nil
531		})
532		return result, err
533	}
