742	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
743	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
744	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
745	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
746	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
747	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
748	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
749	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
750	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
751	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
752	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
753	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
754	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
755	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
756	// 不改变事项、交接进度或班次结束时记录。
757	// 返回的整份结果是查询当时的独立副本，与班次报告同一约定：事项最新信息
758	// （含流经班次、历史事件与关闭时间）、处理经过（含各轮退回原因、补充说明与
759	// 补充时间）和各次交接当前结果（含处理时间与历次退回/补充记录）全部深拷贝，
760	// 处理经过与交接当前结果中同一次补充的时间也各是一份副本。调用方改动结果
761	// 不影响系统保存的数据与其他已取得的结果，系统随后的正常处理（补充后重新
762	// 提交、接收、修改、关闭等）也不会改写这份结果；再次查询才反映最新内容。
763	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
764		itemID = clean(itemID)
765		d := &svc.store.data
766		it, _ := findItem(d, itemID)
767		if it == nil {
768			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
769		}
770		j := ItemJourney{Item: cloneItem(*it)}
771	
772		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
773		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
774		// 该轮重新提交、后续处理）。
775		type keyedEvent struct {
776			ev    JourneyEvent
777			group string // "" 表示事项自身事件，否则为交接编号
778			ord   int    // 同一（时刻、分组）内的先后
779		}
780		var events []keyedEvent
781		seq := 0
782		add := func(ev JourneyEvent, group string) {
783			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
784			seq++
785		}
786	
787		// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
788		// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
789		// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
790		// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
791		merge := newReceivedMerge(it.Events)
792	
793		hs := append([]Handover(nil), d.Handovers...)
794		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
795		for k := range hs {
796			h := &hs[k]
797			e, _ := findEntry(h, itemID)
798			if e == nil {
799				continue
800			}
801			j.HasHandovers = true
802			j.Results = append(j.Results, EntryView{
803				HandoverID: h.ID,
804				FromShift:  h.FromShiftID,
805				ToShift:    h.ToShiftID,
806				Entry:      cloneEntry(*e),
807			})
808	
809			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
810			add(JourneyEvent{
811				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
812				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
813			}, h.ID)
814			for _, r := range e.Rounds {
815				add(JourneyEvent{
816					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
817					Kind: "return", Operator: r.ReturnOperator,
818					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
819					RoundSeq: r.Seq, Reason: r.Reason,
820				}, h.ID)
821				if r.ResubmittedAt != nil {
822					add(JourneyEvent{
823						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
824						Kind: "resubmit", Operator: r.SupplementOperator,
825						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
826						RoundSeq: r.Seq, Supplement: r.Supplement,
827						// 补充时间复制一份：处理经过与交接当前结果中同一次补充
828						// 各属各的副本，改动其中一处不影响另一处与存储记录。
829						SupplementOperator: r.SupplementOperator, SupplementAt: cloneTimePtr(r.SupplementAt),
830					}, h.ID)
831				}
832			}
833			if e.Status == EntryReturned && len(e.Rounds) == 0 {
834				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
835				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
836				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
837				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
838				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
839				ev := JourneyEvent{
840					Kind: "return-incomplete", Operator: e.Operator,
841					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
842					HistoryIncomplete: true,
843				}
844				if validProcessedAt(e.ProcessedAt) {
845					ev.At, ev.TimeKnown = *e.ProcessedAt, true
846				}
847				add(ev, h.ID)
848			}
849			if e.Status.Received() {
850				rcpt := receiptFromEntry(h, e)
851				ev := JourneyEvent{
852					Kind: rcpt.kind, Operator: e.Operator,
853					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
854					TrackingNote: e.TrackingNote,
855					// 继续跟踪当时指定的后续负责人取自交接记录快照，
856					// 之后修改事项负责人不改变这里的历史值。
857					FollowOwner: e.FollowOwner,
858				}
859				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
860				// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
861				// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
862				if rcpt.timeKnown {
863					ev.At, ev.TimeKnown = rcpt.at, true
864				}
865				add(ev, h.ID)
866				// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
867				// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
868				// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
869				// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
870				merge.consider(rcpt)
871			}
872		}
873	
874		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
875		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
876		for i, iev := range it.Events {
877			if iev.Kind == "received" && merge.isUsed(i) {
878				continue
879			}
880			add(JourneyEvent{
881				At: iev.At, TimeKnown: !iev.At.IsZero(),
882				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
883			}, "")
884		}
885	
886		sort.SliceStable(events, func(i, k int) bool {
887			a, b := events[i], events[k]
888			if a.ev.TimeKnown != b.ev.TimeKnown {
889				return a.ev.TimeKnown
890			}
891			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
892				return a.ev.At.Before(b.ev.At)
893			}
894			if a.group != b.group {
895				return a.group < b.group
896			}
897			return a.ord < b.ord
898		})
899		for _, ke := range events {
900			j.Events = append(j.Events, ke.ev)
901		}
902		return j, nil
903	}
