1015	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
1016	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
1017	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
1018	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
1019	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
1020	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
1021	// 也不会改写这份报告；再次查询才反映最新内容。
1022	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
1023		shiftID = clean(shiftID)
1024		d := &svc.store.data
1025		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
1026		sh, _ := findShift(d, shiftID)
1027		if sh == nil {
1028			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
1029		}
1030		rep.Shift = cloneShift(*sh)
1031	
1032		for _, n := range d.Notes {
1033			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
1034				rep.OverlapNotes = append(rep.OverlapNotes, n)
1035			}
1036		}
1037		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
1038	
1039		switch {
1040		case !sh.Closed:
1041			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
1042			rep.Items = currentItemsOfShift(d, sh.ID)
1043		case sh.CloseRecord != nil:
1044			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
1045			rep.ItemsAtClose = true
1046			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
1047			for i, s := range sh.CloseRecord.Items {
1048				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
1049			}
1050			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
1051			for _, s := range rep.CloseItems {
1052				if it, _ := findItem(d, s.ItemID); it != nil {
1053					rep.LatestItems[s.ItemID] = cloneItem(*it)
1054				}
1055			}
1056		default:
1057			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
1058			rep.HistoryIncomplete = true
1059			rep.Items = currentItemsOfShift(d, sh.ID)
1060		}
1061		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
1062		for i := range rep.Items {
1063			rep.Items[i] = cloneItem(rep.Items[i])
1064		}
1065	
1066		for i := range d.Handovers {
1067			h := &d.Handovers[i]
1068			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
1069			if !involved {
1070				continue
1071			}
1072			if h.FromShiftID == sh.ID {
1073				cp := cloneHandover(*h)
1074				rep.Outgoing = &cp
1075			}
1076			if h.ToShiftID == sh.ID {
1077				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
1078			}
1079			for j := range h.Entries {
1080				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
1081					HandoverID: h.ID,
1082					FromShift:  h.FromShiftID,
1083					ToShift:    h.ToShiftID,
1084					Entry:      cloneEntry(h.Entries[j]),
1085				})
1086			}
1087		}
1088		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
1089		for k := range rep.Results {
1090			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
1091		}
