1	package handover
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"testing"
8		"time"
9	)
10	
11	// 本文件的测试把“按班次查询返回的报告是查询当时的独立副本”这一约定变成
12	// 可重复执行的检查：调用方可以暂存报告、改动报告内容用于自己的展示，但改动
13	// 不得影响系统保存的记录、不得影响同一班次先后取得的其他报告；系统随后的
14	// 正常处理（接收、修改、关闭事项）也不得改写已取得的报告。
15	
16	// prepareReportScenario 构建含结束时记录与退回/补充历史的交接场景：
17	// a 已结束（I001、I002 结束时未关闭，I003 结束前已关闭），h 为 a→b 的交接；
18	// I002 被退回一轮后由交班人补充并重新提交（恢复待处理），I001 已确认接收，
19	// 整份交接仍未完成。
20	func prepareReportScenario(t *testing.T, f *fixture) (Shift, Shift, []Item, Handover) {
21		t.Helper()
22		a, b, items := prepareHandover(t, f)
23		h, err := f.svc.CreateHandover(a.ID, b.ID)
24		if err != nil {
25			t.Fatalf("create handover: %v", err)
26		}
27		if _, err := f.svc.ProcessEntry(h.ID, items[1].ID, ActionReturn, "李四", "需要补充细节", "", ""); err != nil {
28			t.Fatalf("return: %v", err)
29		}
30		if _, err := f.svc.ResubmitReturned(h.ID, items[1].ID, "张三", "补充说明如下"); err != nil {
31			t.Fatalf("resubmit: %v", err)
32		}
33		if _, err := f.svc.ProcessEntry(h.ID, items[0].ID, ActionConfirm, "李四", "", "", ""); err != nil {
34			t.Fatalf("confirm: %v", err)
35		}
36		return a, b, items, h
37	}
38	
39	// mustJSON 把报告或记录序列化为 JSON 快照：序列化在取值当时展开全部指针，
40	// 之后即使报告与存储共享内存，快照里保存的仍是取值当时的原值。
41	func mustJSON(t *testing.T, v any) string {
42		t.Helper()
43		raw, err := json.Marshal(v)
44		if err != nil {
45			t.Fatalf("marshal: %v", err)
46		}
47		return string(raw)
48	}
49	
50	// TestShiftReportMutationKeepsStoredFacts：调用方改动报告中的班次摘要、结束时
51	// 记录（含关闭时间）、最新状态对照（内容、负责人、关闭信息、流经班次、处理
52	// 经过）、交接清单与逐项结果中的结果、处理人、处理时间、退回原因与补充说明后，
53	// 再次查询仍得到系统原来保存的事实；先取得的另一份报告也保持原样。
54	func TestShiftReportMutationKeepsStoredFacts(t *testing.T) {
55		f := newFixture(t)
56		a, _, items, h := prepareReportScenario(t, f)
57		idA, idB, idC := items[0].ID, items[1].ID, items[2].ID
58	
59		first, err := f.svc.ShiftReport(a.ID)
60		if err != nil {
61			t.Fatalf("report: %v", err)
62		}
63		second, err := f.svc.ShiftReport(a.ID)
64		if err != nil {
65			t.Fatalf("report again: %v", err)
66		}
67		// 取值当时的 JSON 快照：之后改动报告即使经由共享内存写进存储，
68		// 快照里仍是原值，能识别出任何方向的串改。
69		firstSnapshot := mustJSON(t, first)
70		storedSnapshot := mustJSON(t, mustGetHandover(t, f, h.ID))
71		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
72	
73		// 班次摘要与班次上携带的结束时记录。
74		second.Shift.Owner = "篡改负责人"
75		*second.Shift.ClosedAt = forge
76		second.Shift.CloseRecord.Items[0].Content = "篡改班次上的结束时内容"
77	
78		// 报告的结束时记录：内容、负责人、关闭信息与关闭时间。
79		snap := findCloseItem(second, idC)
80		if snap == nil || !snap.Closed || snap.ClosedAt == nil {
81			t.Fatalf("前置：%s 应在结束时记录中且已关闭", idC)
82		}
83		snap.Content = "篡改关闭事项内容"
84		snap.FollowOwner = "篡改负责人"
85		snap.Closed = false
86		*snap.ClosedAt = forge
87		snap.CloseOperator = "篡改人"
88	
89		// 最新状态对照：内容、负责人、归属与流经班次、关闭信息、处理经过。
90		latest := second.LatestItems[idA]
91		latest.Content = "篡改最新内容"
92		latest.FollowOwner = "篡改负责人"
93		latest.CurrentShiftID = "S999"
94		latest.ShiftIDs = append(latest.ShiftIDs, "S999")
95		latest.Closed = true
96		latest.ClosedAt = &forge
97		latest.CloseOperator = "篡改人"
98		latest.Events = append(latest.Events, ItemEvent{At: forge, Kind: "closed", Operator: "篡改人"})
99		second.LatestItems[idA] = latest
100	
101		// 交接清单中的结果、处理人、处理时间、退回原因与补充说明、完成时间。
102		ea := findEntryOf(t, *second.Outgoing, idA)
103		if ea.ProcessedAt == nil {
104			t.Fatalf("前置：%s 应已确认并记录处理时间", idA)
105		}
106		ea.Status = EntryReturned
107		ea.Operator = "篡改人"
108		*ea.ProcessedAt = forge
109		eb := findEntryOf(t, *second.Outgoing, idB)
110		eb.Rounds[0].Reason = "篡改退回原因"
111		eb.Rounds[0].Supplement = "篡改补充说明"
112		eb.Rounds[0].ReturnOperator = "篡改人"
113		*eb.Rounds[0].SupplementAt = forge
114		*eb.Rounds[0].ResubmittedAt = forge
115		second.Outgoing.CompletedAt = &forge
116	
117		// 逐项结果中的同一交接条目。
118		second.Results[idA][0].Entry.Status = EntryTracking
119		second.Results[idA][0].Entry.Operator = "篡改人"
120		second.Results[idB][0].Entry.Rounds[0].Reason = "篡改结果里的原因"
121		second.Results[idB][0].Entry.Rounds[0].Supplement = "篡改结果里的补充"
122	
123		// 再次查询仍应得到系统原来保存的事实，且与先取得的那份报告完全一致
124		//（既验证存储未被改动，也验证先后取得的两份报告互不影响）。
125		third, err := f.svc.ShiftReport(a.ID)
126		if err != nil {
127			t.Fatalf("report after mutation: %v", err)
128		}
129		if got := mustJSON(t, third); got != firstSnapshot {
130			t.Fatalf("改动报告后再次查询仍应得到系统原来保存的事实\nwant %s\ngot  %s", firstSnapshot, got)
131		}
132	
133		// 系统保存的交接记录整体保持原值。
134		if got := mustJSON(t, mustGetHandover(t, f, h.ID)); got != storedSnapshot {
135			t.Fatalf("系统保存的交接记录不应被报告改动\nwant %s\ngot  %s", storedSnapshot, got)
136		}
137		// 直接核对系统保存的交接记录：退回原因与补充说明仍是原值。
138		stored := mustGetHandover(t, f, h.ID)
139		se := findEntryOf(t, stored, idB)
140		if se.Rounds[0].Reason != "需要补充细节" || se.Rounds[0].Supplement != "补充说明如下" ||
141			se.Rounds[0].ReturnOperator != "李四" || se.Rounds[0].SupplementOperator != "张三" {
142			t.Fatalf("系统保存的退回与补充记录不应被报告改动：%+v", se.Rounds[0])
143		}
144		sae := findEntryOf(t, stored, idA)
145		if sae.Status != EntryConfirmed || sae.Operator != "李四" {
146			t.Fatalf("系统保存的处理结果不应被报告改动：%+v", sae)
147		}
148		if stored.CompletedAt != nil {
149			t.Fatalf("交接尚未完成，报告改动不得写入完成时间")
150		}
151	}
152	
153	// TestShiftReportListAndResultsDoNotShareStorage：同一交接在报告的交接清单
154	// （Outgoing/Incoming）和逐项结果（Results）中各是一份副本，改动其中一处
155	// 不能连带改掉另一处，避免用于核对的两处信息一起被无意修改。
156	func TestShiftReportListAndResultsDoNotShareStorage(t *testing.T) {
157		f := newFixture(t)
158		a, b, items, h := prepareReportScenario(t, f)
159		idA, idB := items[0].ID, items[1].ID
160		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
161	
162		// 交班班次报告：改 Outgoing 清单，逐项结果不受影响。
163		ra, err := f.svc.ShiftReport(a.ID)
164		if err != nil {
165			t.Fatalf("report a: %v", err)
166		}
167		ea := findEntryOf(t, *ra.Outgoing, idA)
168		origProcessedAt := *ea.ProcessedAt
169		ea.Status = EntryReturned
170		ea.Operator = "篡改人"
171		*ea.ProcessedAt = forge
172		got := ra.Results[idA][0].Entry
173		if got.Status != EntryConfirmed || got.Operator != "李四" ||
174			got.ProcessedAt == nil || !got.ProcessedAt.Equal(origProcessedAt) {
175			t.Fatalf("改动交接清单不应连带改掉逐项结果：%+v", got)
176		}
177	
178		// 反向：改逐项结果里的退回历史（含补充时间指针），Outgoing 清单中的
179		// 同一交接不受影响。
180		rb0 := findEntryOf(t, *ra.Outgoing, idB)
181		origSupplementAt := *rb0.Rounds[0].SupplementAt
182		ra.Results[idB][0].Entry.Rounds[0].Reason = "篡改原因"
183		ra.Results[idB][0].Entry.Rounds[0].Supplement = "篡改补充"
184		*ra.Results[idB][0].Entry.Rounds[0].SupplementAt = forge
185		eb := findEntryOf(t, *ra.Outgoing, idB)
186		if eb.Rounds[0].Reason != "需要补充细节" || eb.Rounds[0].Supplement != "补充说明如下" ||
187			!eb.Rounds[0].SupplementAt.Equal(origSupplementAt) {
188			t.Fatalf("改动逐项结果不应连带改掉交接清单：%+v", eb.Rounds[0])
189		}
190	
191		// 接班班次报告：Incoming 清单与逐项结果同样是各自独立的副本。
192		rb, err := f.svc.ShiftReport(b.ID)
193		if err != nil {
194			t.Fatalf("report b: %v", err)
195		}
196		if len(rb.Incoming) != 1 || rb.Incoming[0].ID != h.ID {
197			t.Fatalf("前置：接班班次应看到交接 %s，got %+v", h.ID, rb.Incoming)
198		}
199		ie := findEntryOf(t, rb.Incoming[0], idA)
200		origIncomingProcessedAt := *ie.ProcessedAt
201		ie.Status = EntryReturned
202		ie.Operator = "篡改人"
203		*ie.ProcessedAt = forge
204		gotIn := rb.Results[idA][0].Entry
205		if gotIn.Status != EntryConfirmed || gotIn.Operator != "李四" ||
206			gotIn.ProcessedAt == nil || !gotIn.ProcessedAt.Equal(origIncomingProcessedAt) {
207			t.Fatalf("改动接班清单不应连带改掉逐项结果：%+v", gotIn)
208		}
209		rb.Results[idB][0].Entry.Rounds[0].Reason = "篡改原因"
210		ib := findEntryOf(t, rb.Incoming[0], idB)
211		if ib.Rounds[0].Reason != "需要补充细节" {
212			t.Fatalf("改动逐项结果不应连带改掉接班清单：%+v", ib.Rounds[0])
213		}
214	}
215	
216	// TestEarlierReportSurvivesLaterProcessing：保留报告后，接班人通过已有功能正常
217	// 接收事项、修改并关闭它，系统的新查询反映这些成功操作，但先前报告仍保留
218	// 查询时的事项归属、负责人、关闭情况与交接进度；退回与补充历史、处理时间与
219	// 交接完成时间各属各自报告取得时的事实，旧报告不混入后来新增的经过。
220	func TestEarlierReportSurvivesLaterProcessing(t *testing.T) {
221		f := newFixture(t)
222		a, b, items := prepareHandover(t, f)
223		h, err := f.svc.CreateHandover(a.ID, b.ID)
224		if err != nil {
225			t.Fatalf("create handover: %v", err)
226		}
227		idA, idB := items[0].ID, items[1].ID
228		// 先制造一轮退回/补充，作为旧报告取得时已有的历史。
229		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionReturn, "李四", "需要补充细节", "", ""); err != nil {
230			t.Fatalf("return: %v", err)
231		}
232		if _, err := f.svc.ResubmitReturned(h.ID, idB, "张三", "补充说明如下"); err != nil {
233			t.Fatalf("resubmit: %v", err)
234		}
235	
236		oldA, err := f.svc.ShiftReport(a.ID)
237		if err != nil {
238			t.Fatalf("report a: %v", err)
239		}
240		oldB, err := f.svc.ShiftReport(b.ID)
241		if err != nil {
242			t.Fatalf("report b: %v", err)
243		}
244	
245		// 接班人正常接收两项，随后修改并关闭其中一项。
246		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
247			t.Fatalf("confirm: %v", err)
248		}
249		if _, err := f.svc.UpdateItem(idA, "接班后修改的内容", SeverityUrgent, "新限制", "新负责人"); err != nil {
250			t.Fatalf("update: %v", err)
251		}
252		if _, err := f.svc.CloseItem(idA, "李四"); err != nil {
253			t.Fatalf("close item: %v", err)
254		}
255		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionTrack, "李四", "", "继续盯压力", "王五"); err != nil {
256			t.Fatalf("track: %v", err)
257		}
258	
259		// 新查询反映这些成功操作：交接完成、事项归属与关闭情况都是最新值。
260		newB, err := f.svc.ShiftReport(b.ID)
261		if err != nil {
262			t.Fatalf("report b after processing: %v", err)
263		}
264		if len(newB.Incoming) != 1 || !newB.Incoming[0].Completed() || newB.Incoming[0].CompletedAt == nil {
265			t.Fatalf("新查询应反映交接已完成：%+v", newB.Incoming)
266		}
267		ne := findEntryOf(t, newB.Incoming[0], idA)
268		if ne.Status != EntryConfirmed || ne.Operator != "李四" || ne.ProcessedAt == nil {
269			t.Fatalf("新查询应反映确认结果、处理人与处理时间：%+v", ne)
270		}
271		te := findEntryOf(t, newB.Incoming[0], idB)
272		if te.Status != EntryTracking || te.TrackingNote != "继续盯压力" || te.FollowOwner != "王五" {
273			t.Fatalf("新查询应反映继续跟踪结果：%+v", te)
274		}
275		var newItem *Item
276		for i := range newB.Items {
277			if newB.Items[i].ID == idA {
278				newItem = &newB.Items[i]
279			}
280		}
281		if newItem == nil || !newItem.Closed || newItem.FollowOwner != "新负责人" || newItem.CurrentShiftID != b.ID {
282			t.Fatalf("新查询应反映事项已归属接班班次并关闭：%+v", newItem)
283		}
284	
285		// 先前报告仍保留查询时的交接进度：待处理、无处理人与处理时间、无完成时间。
286		oa := findEntryOf(t, *oldA.Outgoing, idA)
287		if oa.Status != EntryPending || oa.Operator != "" || oa.ProcessedAt != nil {
288			t.Fatalf("旧报告的交接进度不应混入后来的接收：%+v", oa)
289		}
290		if oldA.Outgoing.CompletedAt != nil {
291			t.Fatalf("旧报告的交接完成时间应仍为未记录，got %v", oldA.Outgoing.CompletedAt)
292		}
293		// 先前报告仍保留查询时的事项归属、负责人与关闭情况。
294		latest := oldA.LatestItems[idA]
295		if latest.CurrentShiftID != a.ID || latest.FollowOwner != "李四" || latest.Closed || latest.ClosedAt != nil {
296			t.Fatalf("旧报告应保留查询时的事项归属、负责人与关闭情况：%+v", latest)
297		}
298		// 先前报告保留查询时的退回与补充历史，不混入后来新增的继续跟踪经过。
299		ob := findEntryOf(t, oldB.Incoming[0], idB)
300		if ob.Status != EntryPending || ob.ProcessedAt != nil || ob.TrackingNote != "" {
301			t.Fatalf("旧报告不应混入后来新增的处理经过：%+v", ob)
302		}
303		if len(ob.Rounds) != 1 || ob.Rounds[0].Reason != "需要补充细节" ||
304			ob.Rounds[0].Supplement != "补充说明如下" || ob.Rounds[0].ResubmittedAt == nil {
305			t.Fatalf("旧报告应原样保留查询时的退回与补充历史：%+v", ob.Rounds)
306		}
307		// 旧报告取得时尚未接收任何事项，清单应保持查询时的样子。
308		if len(oldB.Items) != 0 {
309			t.Fatalf("旧报告的事项清单应保持查询时为空，got %d 项", len(oldB.Items))
310		}
311	}
312	
313	// TestEmptyAndLegacyReportsAlsoIndependent：没有事项或关联交接的班次、空清单
314	// 结束的班次与缺少结束时记录的旧数据班次都能正常取得报告，同样遵守独立性
315	// 约定；空清单与缺少历史记录保持区别，旧数据的当前值不能宣称为结束时事实。
316	func TestEmptyAndLegacyReportsAlsoIndependent(t *testing.T) {
317		f := newFixture(t)
318		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
319	
320		// 没有事项、没有关联交接的进行中班次也能正常取得报告。
321		e := mustShift(t, f, "调度", "孙八", tsDay(3, 0, 0), tsDay(3, 8, 0), "")
322		rep, err := f.svc.ShiftReport(e.ID)
323		if err != nil {
324			t.Fatalf("空班次也应能取得报告：%v", err)
325		}
326		if len(rep.Items) != 0 || rep.Outgoing != nil || len(rep.Incoming) != 0 || len(rep.Results) != 0 {
327			t.Fatalf("空班次报告应为空清单：%+v", rep)
328		}
329		// 向报告中塞入假事项、假结果、假交接并改班次摘要，不影响再次查询。
330		rep.Items = append(rep.Items, Item{ID: "I999", Content: "篡改事项"})
331		rep.Results["I999"] = []EntryView{{HandoverID: "H999"}}
332		rep.Outgoing = &Handover{ID: "H999"}
333		rep.Shift.Owner = "篡改负责人"
334		again, err := f.svc.ShiftReport(e.ID)
335		if err != nil {
336			t.Fatalf("report again: %v", err)
337		}
338		if len(again.Items) != 0 || again.Outgoing != nil || len(again.Incoming) != 0 ||
339			len(again.Results) != 0 || again.Shift.Owner != "孙八" {
340			t.Fatalf("改动空班次的报告不应影响再次查询：%+v", again)
341		}
342	
343		// 空清单结束：留下空的结束时记录，与缺少历史记录相区别。
344		if _, err := f.svc.CloseShift(e.ID); err != nil {
345			t.Fatalf("close: %v", err)
346		}
347		closed, err := f.svc.ShiftReport(e.ID)
348		if err != nil {
349			t.Fatalf("report closed: %v", err)
350		}
351		if !closed.ItemsAtClose || closed.HistoryIncomplete || len(closed.CloseItems) != 0 {
352			t.Fatalf("空清单结束应留下空的结束时记录，且不是历史不完整：%+v", closed)
353		}
354		closed.CloseItems = append(closed.CloseItems, CloseItemSnapshot{ItemID: "I999", Content: "篡改事项"})
355		closed.Shift.CloseRecord.Items = append(closed.Shift.CloseRecord.Items, CloseItemSnapshot{ItemID: "I999"})
356		closedAgain, err := f.svc.ShiftReport(e.ID)
357		if err != nil {
358			t.Fatalf("report closed again: %v", err)
359		}
360		if !closedAgain.ItemsAtClose || closedAgain.HistoryIncomplete || len(closedAgain.CloseItems) != 0 {
361			t.Fatalf("改动报告不应影响空清单结束时记录：%+v", closedAgain)
362		}
363	
364		// 旧数据：已结束但缺少结束时记录的班次。
365		dir := t.TempDir()
366		path := filepath.Join(dir, "data.json")
367		closedAt := tsDay(2, 16, 0)
368		createdAt := tsDay(2, 8, 0)
369		data := Data{
370			ShiftSeq: 1,
371			ItemSeq:  1,
372			Shifts: []Shift{
373				{ID: "S001", Position: "调度", Owner: "张三", Start: tsDay(2, 8, 0), End: tsDay(2, 16, 0),
374					CreatedAt: createdAt, Closed: true, ClosedAt: &closedAt},
375			},
376			Items: []Item{{
377				ID: "I001", OriginShiftID: "S001", ShiftIDs: []string{"S001"}, CurrentShiftID: "S001",
378				Content: "旧内容", Severity: SeverityNormal, FollowOwner: "王五", CreatedAt: createdAt,
379			}},
380		}
381		raw, err := json.Marshal(data)
382		if err != nil {
383			t.Fatalf("marshal: %v", err)
384		}
385		if err := os.WriteFile(path, raw, 0o644); err != nil {
386			t.Fatalf("write: %v", err)
387		}
388		store, err := Open(path)
389		if err != nil {
390			t.Fatalf("open: %v", err)
391		}
392		svc := NewService(store)
393	
394		legacy, err := svc.ShiftReport("S001")
395		if err != nil {
396			t.Fatalf("legacy report: %v", err)
397		}
398		if !legacy.HistoryIncomplete || legacy.ItemsAtClose || len(legacy.CloseItems) != 0 {
399			t.Fatalf("旧数据应明确历史记录不完整，当前值不能宣称为结束时事实：%+v", legacy)
400		}
401		if len(legacy.Items) != 1 || legacy.Items[0].Content != "旧内容" {
402			t.Fatalf("旧数据应展示当前事项信息：%+v", legacy.Items)
403		}
404		// 改动旧数据报告中的当前事项（内容、关闭信息、流经班次），再次查询仍得
405		// 原来的当前信息，且仍标明历史不完整、不变成结束时事实。
406		legacy.Items[0].Content = "篡改旧内容"
407		legacy.Items[0].Closed = true
408		legacy.Items[0].ClosedAt = &forge
409		legacy.Items[0].CloseOperator = "篡改人"
410		legacy.Items[0].ShiftIDs = append(legacy.Items[0].ShiftIDs, "S999")
411		legacyAgain, err := svc.ShiftReport("S001")
412		if err != nil {
413			t.Fatalf("legacy report again: %v", err)
414		}
415		if !legacyAgain.HistoryIncomplete || legacyAgain.ItemsAtClose || len(legacyAgain.CloseItems) != 0 {
416			t.Fatalf("改动报告不得把当前值变成结束时事实：%+v", legacyAgain)
417		}
418		if len(legacyAgain.Items) != 1 || legacyAgain.Items[0].Content != "旧内容" ||
419			legacyAgain.Items[0].Closed || len(legacyAgain.Items[0].ShiftIDs) != 1 {
420			t.Fatalf("改动旧数据报告不应影响再次查询的当前信息：%+v", legacyAgain.Items)
421		}
422	}
