94		// 已确认事项的处理时间指针同样与存储脱离。
95		ja, err := f.svc.ItemJourney(idA)
96		if err != nil {
97			t.Fatalf("journey %s: %v", idA, err)
98		}
99		ea := &ja.Results[0].Entry
100		if ea.ProcessedAt == nil {
101			t.Fatalf("前置：%s 应已确认并记录处理时间", idA)
102		}
103		*ea.ProcessedAt = forge
104	
105		// 再次查询仍应得到系统原来保存的事实，且与先取得的那份结果完全一致。
106		third, err := f.svc.ItemJourney(idB)
107		if err != nil {
