109		}
110		if got := mustJSON(t, third); got != firstSnapshot {
111			t.Fatalf("改动结果后再次查询仍应得到系统原来保存的事实\nwant %s\ngot  %s", firstSnapshot, got)
112		}
113		// 系统保存的交接记录与事项记录整体保持原值。
114		if got := mustJSON(t, mustGetHandover(t, f, h.ID)); got != storedHandover {
