119		}
120		stored := mustGetHandover(t, f, h.ID)
121		se := findEntryOf(t, stored, idB)
122		if se.Rounds[0].Reason != "需要补充细节" || se.Rounds[0].Supplement != "补充说明如下" {
123			t.Fatalf("系统保存的退回与补充记录不应被查询结果改动：%+v", se.Rounds[0])
124		}
