169	
170	// TestEarlierJourneySurvivesLaterProcessing：事项被退回后先取得处理经过，交班人
171	// 随后在原交接中补充说明并重新提交、接班人再接收，之后事项被修改并关闭：新查询
172	// 反映这些成功操作，先前那份结果仍保留取得时的退回状态、退回原因、未补充情况、
173	// 负责人、所在班次与流经班次，不混入后来的经过。
174	func TestEarlierJourneySurvivesLaterProcessing(t *testing.T) {
175		f := newFixture(t)
176		a, b, items := prepareHandover(t, f)
177		h, err := f.svc.CreateHandover(a.ID, b.ID)
