194		// 交班人补充并重新提交，接班人确认接收，随后修改并关闭事项。
195		if _, err := f.svc.ResubmitReturned(h.ID, idB, "张三", "补充说明如下"); err != nil {
196			t.Fatalf("resubmit: %v", err)
197		}
