199			t.Fatalf("confirm: %v", err)
200		}
201		if _, err := f.svc.UpdateItem(idB, "接班后修改的内容", SeverityUrgent, "新限制", "新负责人"); err != nil {
202			t.Fatalf("update: %v", err)
203		}
204		if _, err := f.svc.CloseItem(idB, "李四"); err != nil {
205			t.Fatalf("close item: %v", err)
206		}
207	
208		// 新查询反映这些成功操作。
209		fresh, err := f.svc.ItemJourney(idB)
210		if err != nil {
211			t.Fatalf("journey after processing: %v", err)
212		}
213		if fresh.Results[0].Entry.Status != EntryConfirmed || !fresh.Item.Closed ||
214			fresh.Item.FollowOwner != "新负责人" || findJourneyEvent(fresh, "resubmit") == nil {
215			t.Fatalf("新查询应反映补充、接收、修改与关闭：%+v", fresh.Results[0].Entry)
216		}
217	
218		// 先前那份结果仍保留取得时的退回状态、退回原因与未补充情况。
219		oe := old.Results[0].Entry
220		if oe.Status != EntryReturned || oe.Operator != "李四" || oe.ProcessedAt == nil {
221			t.Fatalf("旧结果应保留取得时的退回状态与处理人：%+v", oe)
222		}
223		if oe.Rounds[0].Reason != "需要补充细节" || oe.Rounds[0].Supplement != "" ||
224			oe.Rounds[0].SupplementAt != nil || oe.Rounds[0].ResubmittedAt != nil {
225			t.Fatalf("旧结果应保留取得时的退回原因与未补充情况：%+v", oe.Rounds[0])
226		}
227		// 旧结果中的事项最新信息保持取得时的内容：未关闭、负责人与所在班次不变。
228		if old.Item.Closed || old.Item.ClosedAt != nil || old.Item.FollowOwner != "李四" ||
229			old.Item.CurrentShiftID != a.ID || len(old.Item.ShiftIDs) != 1 {
230			t.Fatalf("旧结果应保留取得时的事项归属、负责人与关闭情况：%+v", old.Item)
231		}
232		// 后来的补充、接收、修改与关闭经过不混入旧结果。
233		for _, kind := range []string{"resubmit", "confirm", "received", "closed"} {
234			if ev := findJourneyEvent(old, kind); ev != nil {
235				t.Fatalf("旧结果不应混入后来的 %s 经过：%+v", kind, ev)
236			}
237		}
238		if ev := findJourneyEvent(old, "updated"); ev != nil {
239			t.Fatalf("旧结果不应混入后来的修改经过：%+v", ev)
240		}
241	}
242	
243	// TestJourneyWithoutHandoverAlsoIndependent：未参与交接的事项仍显示暂无交接
244	// 记录；改动其结果中的事项信息不影响再次查询，也不为独立性补造交接记录。
245	func TestJourneyWithoutHandoverAlsoIndependent(t *testing.T) {
246		f := newFixture(t)
247		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
248		it, err := f.svc.AddItem(a.ID, "未交接事项", SeverityNormal, "", "李四")
249		if err != nil {
250			t.Fatalf("add item: %v", err)
251		}
252		j, err := f.svc.ItemJourney(it.ID)
253		if err != nil {
254			t.Fatalf("journey: %v", err)
255		}
256		if j.HasHandovers || len(j.Results) != 0 {
257			t.Fatalf("未参与交接应显示暂无交接记录：%+v", j.Results)
258		}
