306				}
307			}
308			if ev.TimeKnown && ev.At.Equal(w.failAt) || ev.Operator == w.failedOperator {
309				t.Fatalf("失败尝试不应出现在成功后的处理经过：%+v", ev)
310			}
311		}
312		if journeyClosed != 1 {
313			t.Fatalf("处理经过应只有一次关闭记录，got %d", journeyClosed)
314		}
315		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryConfirmed ||
316			j.Results[0].Entry.Operator != "李四" ||
317			j.Results[0].Entry.ProcessedAt == nil || !j.Results[0].Entry.ProcessedAt.Equal(w.confirmAt) {
318			t.Fatalf("原交接的确认接收结果仍应保留：%+v", j.Results)
319		}
320		jText := FormatItemJourney(j)
321		wantClose := fmt.Sprintf("已关闭（%s 于 %s）", w.successOperator, fmtTime(w.successAt))
322		if !strings.Contains(jText, wantClose) ||
323			!strings.Contains(jText, "关闭 操作人="+w.successOperator) {
324			t.Fatalf("事项查询应显示成功关闭的操作人与时间：\n%s", jText)
325		}
326		if strings.Contains(jText, w.failedOperator) || strings.Contains(jText, fmtTime(w.failAt)) {
327			t.Fatalf("事项查询不应留下失败尝试的痕迹：\n%s", jText)
328		}
329	
330		// 原交接仍保留当时的确认接收结果、接收人和接收时间。
331		h, err := f.svc.GetHandover(w.hID)
332		if err != nil {
333			t.Fatalf("get handover after success: %v", err)
334		}
335		if !h.Completed() || h.CompletedAt == nil || !h.CompletedAt.Equal(w.confirmAt) {
336			t.Fatalf("交接完成时间应仍是接收齐的时刻：%+v", h)
337		}
338		e := findEntryOf(t, h, w.idOpen)
339		if e.Status != EntryConfirmed || e.Operator != "李四" ||
340			e.ProcessedAt == nil || !e.ProcessedAt.Equal(w.confirmAt) {
341			t.Fatalf("原交接的确认接收结果不应改变：%+v", e)
342		}
343	
344		// 上一班结束时记录仍显示该事项当时未关闭、原内容与原负责人；最新状态
345		// 对照才反映它已在接班班次关闭。
346		repA, err := f.svc.ShiftReport(w.aID)
347		if err != nil {
348			t.Fatalf("report prior shift after success: %v", err)
349		}
350		snap := findCloseItem(repA, w.idOpen)
351		if snap == nil || snap.Closed || snap.Content != w.origContent || snap.FollowOwner != "李四" {
352			t.Fatalf("上一班结束时记录应仍显示当时未关闭：%+v", snap)
353		}
354		latest := repA.LatestItems[w.idOpen]
355		if !latest.Closed || latest.CurrentShiftID != w.bID ||
356			latest.CloseOperator != w.successOperator ||
357			latest.ClosedAt == nil || !latest.ClosedAt.Equal(w.successAt) {
358			t.Fatalf("最新状态对照应反映接班班次的成功关闭：%+v", latest)
359		}
360		textA := FormatReport(repA)
361		if !strings.Contains(textA, "结束时未关闭") || !strings.Contains(textA, w.origContent) {
362			t.Fatalf("上一班报告应仍显示结束时未关闭的原记录：\n%s", textA)
363		}
364		if strings.Contains(textA, w.failedOperator) {
365			t.Fatalf("上一班报告不应出现失败尝试的操作人：\n%s", textA)
366		}
367	
368		// 当前班次报告显示该事项已关闭，关闭人与关闭时间属于成功操作；同班次其他
369		// 事项仍未关闭；接班班次本身仍在进行中。
370		repB, err := f.svc.ShiftReport(w.bID)
371		if err != nil {
372			t.Fatalf("report current shift after success: %v", err)
373		}
374		if repB.Shift.Closed || repB.ItemsAtClose {
375			t.Fatalf("接班班次应仍在进行中：%+v", repB.Shift)
376		}
377		if len(repB.Items) != 2 || repB.Items[0].ID != w.idOpen {
378			t.Fatalf("接班班次当前事项应仍为2项，got %+v", repB.Items)
379		}
380		cur := repB.Items[0]
381		if !cur.Closed || cur.CloseOperator != w.successOperator ||
382			cur.ClosedAt == nil || !cur.ClosedAt.Equal(w.successAt) {
383			t.Fatalf("当前班次报告应显示成功关闭的操作人与时间：%+v", cur)
384		}
385		if repB.Items[1].Closed {
386			t.Fatalf("同班次其他事项不应被连带关闭：%+v", repB.Items[1])
387		}
388		textB := FormatReport(repB)
389		if !strings.Contains(textB, wantClose) {
390			t.Fatalf("当前班次报告应显示成功关闭：\n%s", textB)
391		}
392		if strings.Contains(textB, fmtTime(w.failAt)) || strings.Contains(textB, w.failedOperator) {
393			t.Fatalf("当前班次报告不应留下失败尝试的痕迹：\n%s", textB)
394		}
395	}
396	
397	// TestCloseItemSaveFailureAtomicRollback：接班人关闭已确认接收、接班后又修改
398	// 过的未关闭事项时，编号正确、事项未关闭、接班班次进行中、操作人已填写，
399	// 业务条件全部成立、真正进入保存过程后本地写盘失败——关闭操作必须明确返回
400	// 保存错误，不能当成关闭成功；内存与磁盘都回到失败前：事项仍未关闭、关闭
401	// 人与关闭时间未记录，处理经过保留建立、接收与修改而不出现关闭记录，接收
402	// 事实不撤销，上一班结束时记录（当时未关闭）与已关闭事项不受影响，同班次
403	// 其他事项保持原状，原数据文件一个字节不变，重新打开后一致。保存恢复后再
404	// 对同一事项填写操作人关闭，按现有功能成功，只追加这次成功关闭的操作人和
405	// 时间；成功后重复关闭或提交空白操作人都明确拒绝，不覆盖原关闭人或时间、
406	// 不多记关闭经过。
407	func TestCloseItemSaveFailureAtomicRollback(t *testing.T) {
408		f := newFixture(t)
409		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
410		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
411	
412		// 上一班：一项未关闭（随后交给接班班次），一项结束前已关闭。
413		idOpen, err := f.svc.AddItem(a.ID, "上一班遗留的压力异常", SeverityNormal, "", "李四")
414		if err != nil {
415			t.Fatalf("add open item: %v", err)
416		}
417		idClosed, err := f.svc.AddItem(a.ID, "上一班已关闭的巡检事项", SeverityImportant, "需复查记录", "李四")
418		if err != nil {
419			t.Fatalf("add closed item: %v", err)
420		}
421		idClosedAt := tsDay(2, 14, 0)
422		f.svc.nowAt(func() time.Time { return idClosedAt })
423		if _, err := f.svc.CloseItem(idClosed.ID, "张三"); err != nil {
424			t.Fatalf("close item in prior shift: %v", err)
425		}
426		aClosedAt := tsDay(2, 15, 0)
427		f.svc.nowAt(func() time.Time { return aClosedAt })
428		if _, err := f.svc.CloseShift(a.ID); err != nil {
429			t.Fatalf("close prior shift: %v", err)
430		}
431	
432		// 交接完成：未关闭事项由接班人确认接收。
433		handoverCreatedAt := tsDay(2, 16, 30)
434		f.svc.nowAt(func() time.Time { return handoverCreatedAt })
435		h, err := f.svc.CreateHandover(a.ID, b.ID)
436		if err != nil {
437			t.Fatalf("create handover: %v", err)
438		}
439		confirmAt := tsDay(2, 17, 0)
440		f.svc.nowAt(func() time.Time { return confirmAt })
441		if _, err := f.svc.ProcessEntry(h.ID, idOpen.ID, ActionConfirm, "李四", "", "", ""); err != nil {
442			t.Fatalf("confirm receive: %v", err)
443		}
444	
445		// 接班后修改过该事项，使失败前后需要保留的“当前信息”明确可辨。
446		openUpdatedAt := tsDay(2, 18, 0)
447		f.svc.nowAt(func() time.Time { return openUpdatedAt })
448		if _, err := f.svc.UpdateItem(idOpen.ID, "接班后修订的压力异常", SeverityUrgent,
449			"接班后新增限制", "赵六"); err != nil {
450			t.Fatalf("update received item: %v", err)
451		}
452	
453		// 同一接班班次另有一项未关闭事项，用于核对它不被连带影响。
454		otherCreatedAt := tsDay(2, 18, 30)
455		f.svc.nowAt(func() time.Time { return otherCreatedAt })
456		idOther, err := f.svc.AddItem(b.ID, "接班班次的其他事项", SeverityNormal, "", "孙九")
457		if err != nil {
458			t.Fatalf("add other item in current shift: %v", err)
459		}
460	
461		// 前置：事项存在且未关闭、接班班次进行中、交接已完成。
462		pre, _ := f.svc.GetItem(idOpen.ID)
463		if pre.Closed || pre.CurrentShiftID != b.ID {
464			t.Fatalf("前置：事项应未关闭且属于接班班次：%+v", pre)
465		}
466		if preShift, _ := f.svc.GetShift(b.ID); preShift.Closed {
467			t.Fatalf("前置：接班班次应仍在进行中")
468		}
469		if preH, _ := f.svc.GetHandover(h.ID); !preH.Completed() {
470			t.Fatalf("前置：交接应已确认接收完成")
471		}
472	
473		want := failedItemCloseExpectations{
474			aID: a.ID, bID: b.ID, hID: h.ID,
475			idOpen: idOpen.ID, idOther: idOther.ID, idClosed: idClosed.ID,
476			aClosedAt:         aClosedAt,
477			idClosedAt:        idClosedAt,
478			handoverCreatedAt: handoverCreatedAt,
479			confirmAt:         confirmAt,
480			openUpdatedAt:     openUpdatedAt,
481			otherCreatedAt:    otherCreatedAt,
482			failAt:            tsDay(2, 19, 0),
483			successAt:         tsDay(2, 20, 0),
484			origContent:       "上一班遗留的压力异常",
485			origConstraints:   "",
486			midContent:        "接班后修订的压力异常",
487			midConstraints:    "接班后新增限制",
488			midFollow:         "赵六",
489			midSeverity:       SeverityUrgent,
490			failedOperator:    "接班人王五",
491			successOperator:   "接班人郑七",
492		}
493	
494		// 记录失败前已落盘的文件内容，并固定失败尝试的关闭时刻。
495		rawBefore, err := os.ReadFile(f.store.Path())
496		if err != nil {
497			t.Fatalf("read data file: %v", err)
498		}
499		f.svc.nowAt(func() time.Time { return want.failAt })
500	
501		// 使下一次写盘在原子保存阶段失败，然后由接班人填写操作人关闭该事项。
502		breakSaving(t, f)
503		got, err := f.svc.CloseItem(idOpen.ID, want.failedOperator)
504		// 操作输出必须明确报错：这是保存错误而不是业务拒绝（不能用编号不存在、
505		// 事项已关闭、班次已结束或操作人为空来冒充），也不能把回滚掉的关闭状态
506		// 当作关闭结果返回。
507		if err == nil {
508			t.Fatalf("保存失败时关闭事项应返回错误，不能当成关闭成功")
509		}
510		if !strings.Contains(err.Error(), "写入数据文件失败") {
511			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
512		}
513		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) ||
514			errors.Is(err, ErrNotFound) || errors.Is(err, ErrShiftClosed) {
515			t.Fatalf("编号正确、未关闭、班次进行中且操作人已填写时的保存失败不应被报告为业务校验错误，got %v", err)
516		}
517		if !reflect.DeepEqual(got, Item{}) {
518			t.Fatalf("保存失败不得把回滚掉的关闭状态当作关闭结果返回：%+v", got)
519		}
520	
521		// 当前打开的数据上查看事项、交接与报告，应看到失败前的事实，而不是只
522		// 保证文件没变、查询却显示已经关闭。
523		assertItemStillOpenAfterFailedClose(t, f, want)
524	
525		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
526		rawAfter, err := os.ReadFile(f.store.Path())
527		if err != nil {
528			t.Fatalf("read data file after failure: %v", err)
529		}
530		if string(rawAfter) != string(rawBefore) {
531			t.Fatalf("保存失败不得改动既有数据文件，失败的关闭不能成为其中的业务事实")
532		}
533	
534		// 退出后重新打开同一数据文件：事项仍未关闭，原有的接收与修改经过都在。
535		f.reopen(t)
536		assertItemStillOpenAfterFailedClose(t, f, want)
537	
538		// 保存恢复后，接班人再对同一事项填写操作人并关闭：按现有功能成功。
539		restoreSaving(t, f)
540		f.svc.nowAt(func() time.Time { return want.successAt })
541		closed, err := f.svc.CloseItem(idOpen.ID, want.successOperator)
542		if err != nil {
543			t.Fatalf("保存恢复后关闭事项应成功：%v", err)
544		}
545		if !closed.Closed || closed.CloseOperator != want.successOperator ||
546			closed.ClosedAt == nil || !closed.ClosedAt.Equal(want.successAt) {
547			t.Fatalf("成功关闭的返回结果应为本次操作人与时间：%+v", closed)
548		}
549		assertItemClosedAfterRecovery(t, f, want)
550	
551		// 成功落盘的文件只包含成功事实，不包含失败尝试时刻或失败尝试的操作人。
552		rawSuccess, err := os.ReadFile(f.store.Path())
553		if err != nil {
554			t.Fatalf("read data file after success: %v", err)
555		}
556		if !strings.Contains(string(rawSuccess), want.successAt.Format("2006-01-02T15:04:05-07:00")) {
557			t.Fatalf("成功关闭时间应已写入数据文件")
558		}
559		if strings.Contains(string(rawSuccess), want.failAt.Format("2006-01-02T15:04:05-07:00")) {
560			t.Fatalf("失败的关闭尝试时刻不应留在数据文件中")
561		}
562		if strings.Contains(string(rawSuccess), want.failedOperator) {
563			t.Fatalf("失败尝试填写的操作人不应写入数据文件")
564		}
565	
566		// 已成功关闭的事项再次关闭：明确拒绝，不覆盖原关闭人或时间，也不多记
567		// 一条关闭经过。
568		if _, err := f.svc.CloseItem(idOpen.ID, "赵六"); !errors.Is(err, ErrHandoverState) {
569			t.Fatalf("重复关闭已关闭事项应报 ErrHandoverState，got %v", err)
570		} else if !strings.Contains(err.Error(), "已关闭") {
571			t.Fatalf("重复关闭的错误信息应指出事项已关闭，got %v", err)
572		}
573		retry, _ := f.svc.GetItem(idOpen.ID)
574		if !retry.Closed || retry.CloseOperator != want.successOperator ||
575			retry.ClosedAt == nil || !retry.ClosedAt.Equal(want.successAt) ||
576			joinStrings(itemEventKinds(retry)) != "created,received,updated,closed" {
577			t.Fatalf("重复关闭被拒绝后原关闭人、关闭时间与处理经过应保持：%+v", retry)
578		}
579	
580		// 操作人为空或只有空白：同样拒绝并保留原状态。
581		if _, err := f.svc.CloseItem(idOpen.ID, "   "); !errors.Is(err, ErrInvalidInput) {
582			t.Fatalf("空白操作人关闭应报 ErrInvalidInput，got %v", err)
583		}
584		blank, _ := f.svc.GetItem(idOpen.ID)
585		if !blank.Closed || blank.CloseOperator != want.successOperator ||
586			blank.ClosedAt == nil || !blank.ClosedAt.Equal(want.successAt) ||
587			joinStrings(itemEventKinds(blank)) != "created,received,updated,closed" {
588			t.Fatalf("空白操作人被拒绝后原状态应保持：%+v", blank)
589		}
590	
591		// 退出重开后，成功关闭的事实、原有历史与上一班原始记录都完整保留，
592		// 失败尝试仍无痕迹；重复关闭依旧被拒绝。
593		f.reopen(t)
594		assertItemClosedAfterRecovery(t, f, want)
595		if _, err := f.svc.CloseItem(idOpen.ID, "赵六"); !errors.Is(err, ErrHandoverState) {
596			t.Fatalf("重开后重复关闭仍应拒绝，got %v", err)
597		}
598	}
