1	package handover
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// failedCloseExpectations 汇总结束失败尝试发生前已保存的业务事实，供 reopen
13	// 前后用同一组期望核对，以及成功结束后对照。
14	type failedCloseExpectations struct {
15		aID, bID, hID           string
16		idOpen, idNew, idClosed string
17		aClosedAt               time.Time // 上一班成功结束的时间（其结束时记录不受影响）
18		idClosedAt              time.Time // 上一班已关闭事项的关闭时间
19		handoverCreatedAt       time.Time
20		trackAt                 time.Time // 唯一交接事项成功接收（继续跟踪）的时间
21		openUpdatedAt           time.Time // 接班后第一次修改未关闭事项的时间
22		idNewClosedAt           time.Time // 本班新增事项的关闭时间
23		failAt                  time.Time // 失败的结束尝试时刻（不应留下任何痕迹）
24		reUpdateAt              time.Time // 保存恢复后再次修改未关闭事项的时间
25		successAt               time.Time // 真正成功结束本班的时间
26		origContent             string
27		origConstraints         string
28		trackNote               string
29		trackFollow             string // 接收当时指定的后续负责人（交接记录保存）
30		midContent              string
31		midConstraints          string
32		midFollow               string
33		midSeverity             Severity
34		finalContent            string
35		finalConstraints        string
36		finalFollow             string
37		finalSeverity           Severity
38	}
39	
40	// assertStillOpenAfterFailedClose 用当前打开的数据核对：保存失败后本班仍在
41	// 进行中，没有结束时间，也没有结束时事项记录；失败前已保存的事项、交接与
42	// 上一班结束时记录全部原样保留，本次失败不成为任何业务事实。
43	func assertStillOpenAfterFailedClose(t *testing.T, f *fixture, w failedCloseExpectations) {
44		t.Helper()
45	
46		// 失败尝试不新增班次或交接，也不复制事项。
47		if hs := f.svc.ListShifts(); len(hs) != 2 {
48			t.Fatalf("失败尝试不应新增班次，got %d 个：%+v", len(hs), hs)
49		}
50		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != w.hID {
51			t.Fatalf("失败尝试不应新增交接：%+v", hs)
52		}
53		for _, id := range []string{w.idOpen, w.idNew, w.idClosed} {
54			if n := countItems(f, id); n != 1 {
55				t.Fatalf("失败尝试不应复制事项，编号 %s 出现 %d 次", id, n)
56			}
57		}
58	
59		// 本班仍在进行中：没有结束时间，也没有结束时记录。
60		b, err := f.svc.GetShift(w.bID)
61		if err != nil {
62			t.Fatalf("get shift: %v", err)
63		}
64		if b.Closed || b.ClosedAt != nil || b.CloseRecord != nil {
65			t.Fatalf("保存失败后班次应仍在进行中、无结束时间与结束时记录：%+v", b)
66		}
67	
68		// 查看本班：事项区仍展示当前信息，不被标成结束时记录或历史不完整；
69		// 本班只含两项（本班新增已关闭项、上一班交来仍未关闭项），各一次并按
70		// 编号排列；上一班已关闭的事项不属于本班，不能被拉进本班清单。
71		repB, err := f.svc.ShiftReport(w.bID)
72		if err != nil {
73			t.Fatalf("report b: %v", err)
74		}
75		if repB.Shift.Closed || repB.ItemsAtClose || repB.HistoryIncomplete {
76			t.Fatalf("进行中班次不应出现结束时记录或历史不完整标记：%+v", repB.Shift)
77		}
78		if len(repB.CloseItems) != 0 {
79			t.Fatalf("失败尝试不应生成结束时事项记录：%+v", repB.CloseItems)
80		}
81		if len(repB.Items) != 2 {
82			t.Fatalf("本班当前事项应为2项，got %d：%+v", len(repB.Items), repB.Items)
83		}
84		if repB.Items[0].ID != w.idOpen || repB.Items[1].ID != w.idNew {
85			t.Fatalf("事项应按编号排列且各出现一次：%s %s", repB.Items[0].ID, repB.Items[1].ID)
86		}
87		cur := map[string]Item{}
88		for _, it := range repB.Items {
89			cur[it.ID] = it
90		}
91		// 接收到的未关闭事项：保留接班后修改过的内容、严重程度、限制条件与负责人，
92		// 仍在本班、仍未关闭，不能退回上一班，也不能多记一条关闭。
93		op := cur[w.idOpen]
94		if op.Content != w.midContent || op.Severity != w.midSeverity ||
95			op.Constraints != w.midConstraints || op.FollowOwner != w.midFollow {
96			t.Fatalf("未关闭事项应保持接班后修改的当前信息：%+v", op)
97		}
98		if op.Closed || op.ClosedAt != nil || op.CloseOperator != "" {
99			t.Fatalf("未关闭事项不能因失败尝试变成已关闭：%+v", op)
100		}
101		if op.OriginShiftID != w.aID || op.CurrentShiftID != w.bID ||
102			len(op.ShiftIDs) != 2 || op.ShiftIDs[0] != w.aID || op.ShiftIDs[1] != w.bID {
103			t.Fatalf("接收到的事项不能退回上一班，编号与流经班次应保持：%+v", op)
104		}
105		// 本班新增且已关闭的事项：关闭人与关闭时间保持原样，不能被重新打开。
106		nw := cur[w.idNew]
107		if !nw.Closed || nw.CloseOperator != "李四" ||
108			nw.ClosedAt == nil || !nw.ClosedAt.Equal(w.idNewClosedAt) {
109			t.Fatalf("本班已关闭事项的关闭人与关闭时间应保持原样：%+v", nw)
110		}
111		if nw.OriginShiftID != w.bID || nw.CurrentShiftID != w.bID ||
112			len(nw.ShiftIDs) != 1 || nw.ShiftIDs[0] != w.bID {
113			t.Fatalf("本班新增事项所在班次应保持：%+v", nw)
114		}
115		// 上一班已关闭事项仍在上一班、保持关闭。
116		old, err := f.svc.GetItem(w.idClosed)
117		if err != nil {
118			t.Fatalf("get closed item: %v", err)
119		}
120		if !old.Closed || old.CloseOperator != "张三" ||
121			old.ClosedAt == nil || !old.ClosedAt.Equal(w.idClosedAt) {
122			t.Fatalf("上一班已关闭事项不能被重新打开：%+v", old)
123		}
124		if old.OriginShiftID != w.aID || old.CurrentShiftID != w.aID ||
125			len(old.ShiftIDs) != 1 || old.ShiftIDs[0] != w.aID {
126			t.Fatalf("上一班已关闭事项所在班次应保持：%+v", old)
127		}
128	
129		// 交接：接收结果、处理人、处理时间与完成时间保留；交接记录里继续跟踪
130		// 当时的跟踪说明与后续负责人是接收时刻保存的值，不被接班后的修改改写。
131		h, err := f.svc.GetHandover(w.hID)
132		if err != nil {
133			t.Fatalf("get handover: %v", err)
134		}
135		if !h.Completed() || h.CompletedAt == nil || !h.CompletedAt.Equal(w.trackAt) {
136			t.Fatalf("既有交接的接收结果与完成时间应保留：%+v", h)
137		}
138		if !h.CreatedAt.Equal(w.handoverCreatedAt) || h.FromShiftID != w.aID || h.ToShiftID != w.bID {
139			t.Fatalf("交接编号、两班关系与发起时间应保留：%+v", h)
140		}
141		if len(h.Entries) != 1 {
142			t.Fatalf("交接清单不应变化，got %d 项", len(h.Entries))
143		}
144		e := findEntryOf(t, h, w.idOpen)
145		if e.Status != EntryTracking || e.Operator != "李四" ||
146			e.ProcessedAt == nil || !e.ProcessedAt.Equal(w.trackAt) ||
147			e.TrackingNote != w.trackNote || e.FollowOwner != w.trackFollow {
148			t.Fatalf("接收方式、处理人、处理时间、跟踪说明与当时负责人应保留：%+v", e)
149		}
150		if len(e.Rounds) != 0 {
151			t.Fatalf("失败尝试不应产生退回/补充经过：%+v", e.Rounds)
152		}
153	
154		// 上一班保持成功结束，其结束时记录仍是上一班自己结束时的内容：
155		// 未关闭事项保留原内容、原负责人且当时未关闭；已关闭事项保留关闭人与时间。
156		sa, err := f.svc.GetShift(w.aID)
157		if err != nil {
158			t.Fatalf("get shift a: %v", err)
159		}
160		if !sa.Closed || sa.ClosedAt == nil || !sa.ClosedAt.Equal(w.aClosedAt) || sa.CloseRecord == nil {
161			t.Fatalf("上一班的结束状态、结束时间与结束时记录应保留：%+v", sa)
162		}
163		repA, err := f.svc.ShiftReport(w.aID)
164		if err != nil {
165			t.Fatalf("report a: %v", err)
166		}
167		if !repA.ItemsAtClose || len(repA.CloseItems) != 2 {
168			t.Fatalf("上一班结束时记录应保留2项，got %+v", repA.CloseItems)
169		}
170		snapOpen := findCloseItem(repA, w.idOpen)
171		if snapOpen == nil || snapOpen.Content != w.origContent ||
172			snapOpen.Severity != SeverityNormal || snapOpen.Constraints != w.origConstraints ||
173			snapOpen.FollowOwner != "李四" || snapOpen.Closed {
174			t.Fatalf("上一班记录中的未关闭事项应保持结束时原样：%+v", snapOpen)
175		}
176		snapClosed := findCloseItem(repA, w.idClosed)
177		if snapClosed == nil || !snapClosed.Closed || snapClosed.CloseOperator != "张三" ||
178			snapClosed.ClosedAt == nil || !snapClosed.ClosedAt.Equal(w.idClosedAt) {
179			t.Fatalf("上一班记录中的已关闭事项应保持关闭人与关闭时间：%+v", snapClosed)
180		}
181	
182		// 展示层与保存事实一致：本班事项区是当前信息而非结束时记录，不出现失败
183		// 尝试的结束时间；上一班仍展示自己的结束时记录。
184		textB := FormatReport(repB)
185		if strings.Contains(textB, "结束时记录") || strings.Contains(textB, fmtTime(w.failAt)) {
186			t.Fatalf("本班报告不应出现结束时记录或失败尝试时刻：\n%s", textB)
187		}
188		if !strings.Contains(textB, "\n事项：\n") || !strings.Contains(textB, w.midContent) ||
189			!strings.Contains(textB, "后续负责人："+w.midFollow) {
190			t.Fatalf("本班报告应展示未关闭事项的当前信息：\n%s", textB)
191		}
192		if !strings.Contains(textB, fmt.Sprintf("已关闭（李四 于 %s）", fmtTime(w.idNewClosedAt))) {
193			t.Fatalf("本班报告应保留已关闭事项的关闭人与关闭时间：\n%s", textB)
194		}
195		if !strings.Contains(FormatShift(b), "[进行中]") {
196			t.Fatalf("班次摘要应显示进行中：%s", FormatShift(b))
197		}
198		if !strings.Contains(textB, "已完成 "+fmtTime(w.trackAt)) ||
199			!strings.Contains(textB, w.trackFollow) {
200			t.Fatalf("本班报告中的接班交接应保留完成时间与接收当时的负责人：\n%s", textB)
201		}
202		textA := FormatReport(repA)
203		if !strings.Contains(textA, "结束时记录") || !strings.Contains(textA, w.origContent) ||
204			!strings.Contains(textA, "结束时后续负责人：李四") {
205			t.Fatalf("上一班报告应仍展示自己的原始结束时记录：\n%s", textA)
206		}
207	
208		// 事项处理经过只含失败前已保存的事实，不混入失败尝试时刻；接收到的事项
209		// 保留接收经过，两个已关闭事项没有新的关闭/重开经过。
210		jOpen, err := f.svc.ItemJourney(w.idOpen)
211		if err != nil {
212			t.Fatalf("journey open: %v", err)
213		}
214		if got := joinStrings(journeyKinds(jOpen)); got != "created,handover-init,track,updated" {
215			t.Fatalf("未关闭事项处理经过应只含失败前事实，got %s", got)
216		}
217		updates := 0
218		for _, ev := range jOpen.Events {
