		storedSnap.ClosedAt == nil || !storedSnap.ClosedAt.Equal(closedAtOrig) {
		t.Fatalf("结束时记录应保留当时的关闭人与关闭时间，不受关闭结果改写影响：%+v", storedSnap)
	}
	// 事项本身保存的关闭信息同样不变。
