	// 结束操作刚返回时取一份原班次事实快照，作为后续正常保存后的对照基准。
	storedSnapshot := mustJSON(t, mustGetShift(t, f, a.ID))

	// 调用方为本地展示篡改手中的结束结果。
	forge := time.Date(2033, 9, 8, 7, 6, 5, 0, time.UTC)
